using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text.Json;
using Leptonica;

namespace Leptonica.Managed.Tests.Reg;

/// <summary>
/// [Fact] for a ported regression test: skipped when the golden files or the
/// converted input images are not available (they are generated by
/// tools/native/goldens.ps1 and tools/native/inputs.ps1).
/// </summary>
/// <remarks>
/// A test with a known golden mismatch is marked <c>Skip = "golden mismatch ..."</c>.
/// In triage mode (environment variable LEPT_REGTRIAGE = path of a jsonl file) such
/// tests run, and every failed check is appended to that file.
/// </remarks>
public sealed class RegFactAttribute : FactAttribute
{
    public RegFactAttribute()
    {
        if (TestPaths.GoldenDir == null)
            base.Skip = "testdata/golden not found; run tools/native/build.ps1 and tools/native/goldens.ps1";
        else if (!Directory.Exists(TestPaths.ProgDir))
            base.Skip = "testdata/prog not found";
    }

    public override string Skip
    {
        get => base.Skip;
        set {
            if (RegTest.TriageFile != null && value != null &&
                value.StartsWith("golden mismatch", StringComparison.Ordinal))
                return;
            base.Skip = value!;
        }
    }
}

/// <summary>Locations of the repository test data.</summary>
public static class TestPaths
{
    /// <summary>Repository root: the folder containing Leptonica.Managed.slnx.</summary>
    public static readonly string RepoRoot = FindRepoRoot();

    /// <summary>testdata/golden, or null if it does not exist.</summary>
    public static readonly string? GoldenDir = Directory.Exists(Path.Combine(RepoRoot, "testdata", "golden"))
                                               ? Path.Combine(RepoRoot, "testdata", "golden") : null;

    /// <summary>Upstream prog/ directory with the input images of the regression tests.</summary>
    public static readonly string ProgDir = Path.Combine(RepoRoot, "testdata", "prog");

    /// <summary>
    /// Creates a test output directory beneath both interpretations of /tmp.
    /// Leptonica path helpers rewrite /tmp to Path.GetTempPath(), while raw .NET and
    /// LibTiff file APIs resolve /tmp as the current drive's root-level tmp directory.
    /// Unlike Utils.LeptMkdir, this is not gated by the process-wide LeptDebugOK flag.
    /// </summary>
    public static string EnsureLeptTempDir(string subdir)
    {
        if (string.IsNullOrWhiteSpace(subdir) || Path.IsPathRooted(subdir))
            throw new ArgumentException("Expected a relative Leptonica temp subdirectory", nameof(subdir));

        string relative = subdir.Replace('\\', Path.DirectorySeparatorChar)
                                .Replace('/', Path.DirectorySeparatorChar);
        if (relative.Split(Path.DirectorySeparatorChar).Any(part => part is "" or "." or ".."))
            throw new ArgumentException("Invalid Leptonica temp subdirectory", nameof(subdir));

        string mappedTempRoot = Utils.GenPathname("/tmp", null);
        string mappedPath = Path.Combine(mappedTempRoot, "lept", relative);
        string rawPath = Path.Combine(Path.GetFullPath("/tmp"), "lept", relative);
        Directory.CreateDirectory(mappedPath);
        Directory.CreateDirectory(rawPath);
        return mappedPath;
    }

    /// <summary>
    /// testdata/inputs (non-png input images converted to png by the native build),
    /// or null if it does not exist.
    /// </summary>
    public static readonly string? InputDir = Directory.Exists(Path.Combine(RepoRoot, "testdata", "inputs"))
                                              ? Path.Combine(RepoRoot, "testdata", "inputs") : null;

    /// <summary>Full path to an input file inside testdata/prog/.</summary>
    public static string ProgFile(string name) => Path.Combine(ProgDir, name);

    /// <summary>
    /// pixRead() of an input image of the regression tests, by its name in prog/.
    /// When testdata/inputs is present, non-png inputs use their pre-decoded png
    /// copy so existing golden comparisons remain bit-exact; otherwise they are
    /// decoded directly from testdata/prog/.
    /// </summary>
    public static Pix ReadInput(string name)
    {
        string path = Path.Combine(ProgDir, name);
        lock (PngReadLock) {
            if (Path.GetExtension(name).Equals(".png", StringComparison.OrdinalIgnoreCase))
                return Pix.Read(path);
            if (InputDir != null) {
                string pngConv = Path.Combine(InputDir, name + ".png");
                if (File.Exists(pngConv))
                    return Pix.Read(pngConv);
            }
            return Pix.Read(path);
        }
    }

    /// <summary>
    /// Like <see cref="ReadInput"/>, for an image that is 16 bpp in its original
    /// format (e.g. test16.tif): read without stripping 16 --&gt; 8 bpp.
    /// </summary>
    public static Pix ReadInput16(string name)
    {
        string path = Path.Combine(ProgDir, name);
        lock (PngReadLock) {
            Pix.PngSetReadStrip16To8(0);
            try {
                if (InputDir != null) {
                    string pngConv = Path.Combine(InputDir, name + ".png");
                    if (File.Exists(pngConv))
                        return Pix.Read(pngConv);
                }
                return Pix.Read(path);
            } finally {
                Pix.PngSetReadStrip16To8(1);
            }
        }
    }

    /// <summary>Serializes png reads, because of the global 16 --> 8 bpp strip flag.</summary>
    public static readonly object PngReadLock = new();

    private static string FindRepoRoot()
    {
        string? dir = AppContext.BaseDirectory;
        while (dir != null && !File.Exists(Path.Combine(dir, "Leptonica.Managed.slnx")))
            dir = Path.GetDirectoryName(dir);
        return dir ?? throw new InvalidOperationException("Leptonica.Managed.slnx not found");
    }
}

/// <summary>
/// Regression test parameters and checks: the port of regutils.c (L_REGPARAMS,
/// regTest*) for the C# test suite.
/// </summary>
/// <remarks>
/// <para>
/// Only the "compare" mode exists: the golden files are always the ones made by the
/// C library (tools/native/goldens.ps1), in testdata/golden. The indexing and the local
/// file names are the same as in C, so a ported foo_reg.c reads line by line like
/// the original and its checks hit the same golden files.
/// </para>
/// <para>
/// Differences from C, all in how a local result is compared with its golden file:
/// (1) Image files are compared by decoded pixels (pixEqual), not by bytes, because
///     the managed encoders do not produce the same bytes as libpng etc.
/// (2) regTestWritePixAndCheck() with a format other than png compares, through png,
///     with the lossless copy golden_NN.raw.png that the patched C build saves
///     next to each such golden file.
/// (3) Failures are collected and reported by <see cref="Cleanup"/> as a test failure.
/// </para>
/// </remarks>
public sealed class RegTest
{
    private readonly List<string> failures = new();

    /// <summary>Triage mode: the jsonl file that receives the failed checks, or null.</summary>
    public static readonly string? TriageFile =
        Environment.GetEnvironmentVariable("LEPT_REGTRIAGE") is { Length: > 0 } f ? f : null;

    private static readonly object TriageLock = new();

    /// <summary>Name of the test, without "_reg".</summary>
    public string TestName { get; }

    /// <summary>Index of the last check; 0-based, -1 before the first check.</summary>
    public int Index { get; private set; } = -1;

    /// <summary>Always false: there is no display mode.</summary>
    public bool Display => false;

    /// <summary>True while no check has failed.</summary>
    public bool Success => failures.Count == 0;

    // leptonica: regTestSetup (regutils.c)
    /// <param name="testname">name of the C test without "_reg", e.g. "pngio"</param>
    public RegTest(string testname)
    {
        TestName = testname;
        Pix.LeptDebugOK = true;  /* required for testing */

            /* Each C reg test is a fresh process, which starts with srand(1);
             * here the generator state is per thread and shared with earlier tests */
        CRand.Seed(1);

            /* Make sure the lept/regout subdirectory exists */
        TestPaths.EnsureLeptTempDir("regout");
    }

    // leptonica: regTestCleanup (regutils.c)
    /// <summary>Fails the xunit test if any check failed.</summary>
    public void Cleanup()
    {
        if (failures.Count > 0)
            Assert.Fail($"FAILURE: {TestName}_reg\n" + string.Join("\n", failures));
    }

    // leptonica: regTestCompareValues (regutils.c)
    /// <param name="val1">typ. the golden value</param>
    /// <param name="val2">typ. the value computed</param>
    /// <param name="delta">allowed max absolute difference</param>
    public void CompareValues(float val1, float val2, float delta)
    {
        Index++;
        float diff = Math.Abs(val2 - val1);

            /* Record on failure */
        if (diff > delta) {
            Fail($"value comparison for index {Index}\n" +
                 $"difference = {diff:F6} but allowed delta = {delta:F6}",
                 "values", null, null, $"golden {val1:G9}, computed {val2:G9}, delta {delta:G9}");
        }
    }

    // leptonica: regTestCompareStrings (regutils.c)
    public void CompareStrings(ReadOnlySpan<byte> string1, ReadOnlySpan<byte> string2)
    {
        Index++;
        bool same = Utils.BinaryCompare(string1, string2);

            /* Output on failure */
        if (!same) {
                /* Write the two strings to file */
            Utils.BinaryWrite($"/tmp/lept/regout/string1_{Index}_{string1.Length}", "w", string1);
            Utils.BinaryWrite($"/tmp/lept/regout/string2_{Index}_{string2.Length}", "w", string2);

                /* Report comparison failure */
            Fail($"string comp for index {Index}; written to /tmp/lept/regout/string*_{Index}_*",
                 "strings", $"/tmp/lept/regout/string2_{Index}_{string2.Length}",
                 $"/tmp/lept/regout/string1_{Index}_{string1.Length}", null);
        }
    }

    // leptonica: regTestComparePix (regutils.c)
    public void ComparePix(Pix pix1, Pix pix2)
    {
        Index++;
        bool same = Pix.Equal(pix1, pix2);

            /* Record on failure */
        if (!same) {
            string? name1 = null, name2 = null;
            if (TriageFile != null) {
                name1 = $"/tmp/lept/regout/{TestName}.{Index:D2}.cmp1.png";
                name2 = $"/tmp/lept/regout/{TestName}.{Index:D2}.cmp2.png";
                Pix.WritePng(name1, pix1, 0.0f);
                Pix.WritePng(name2, pix2, 0.0f);
            }
            Fail($"pix comparison for index {Index}", "pixpair", name2, name1, null);
        }
    }

    // leptonica: regTestCompareSimilarPix (regutils.c)
    /// <param name="mindiff">at least 1; ignore pixel differences below this value</param>
    /// <param name="maxfract">maximum fraction of pixels allowed to have diff greater than or equal to mindiff</param>
    /// <param name="printstats">use 1 to print normalized histogram to stderr</param>
    public void CompareSimilarPix(Pix pix1, Pix pix2, int mindiff, float maxfract, int printstats)
    {
        Index++;
        int factor = Math.Max(pix1.Width, pix1.Height) / 400;
        factor = Math.Max(1, Math.Min(factor, 4));   /* between 1 and 4 */
        bool similar = pix1.TestForSimilarity(pix2, factor, mindiff, maxfract, 0.0f,
                                              printstats);

            /* Record on failure */
        if (!similar)
            Fail($"similarity comp for index {Index}");
    }

    // leptonica: regTestCheckFile (regutils.c)
    /// <summary>Checks a local file against the golden file with the next index.</summary>
    /// <param name="localname">name of output file from reg test</param>
    public void CheckFile(string localname)
    {
        Index++;

            /* Generate the golden file name */
        string ext = SplitPathAtExtension(localname);
        string goldenname = GoldenName(Index, ext);
        if (!File.Exists(goldenname)) {
            Fail($"index {Index}: golden file {goldenname} not found", "missing", localname, null, null);
            return;
        }

        bool same = FilesHaveSameContent(Utils.GenPathname(localname, null), goldenname, out string detail);
        if (!same)
            Fail($"index {Index}: comparing {localname} with {goldenname}{detail}",
                 "file", localname, goldenname, detail);
    }

    // leptonica: regTestCompareFiles (regutils.c)
    /// <summary>Compares two golden files of this test with each other.</summary>
    /// <remarks>
    /// This only reads golden files, so the result is the same as in C; it is
    /// kept so that the check indices stay in step with the C test.
    /// </remarks>
    public void CompareFiles(int index1, int index2)
    {
        if (index1 < 0 || index2 < 0)
            throw new ArgumentException("index1 and/or index2 is negative");
        if (index1 == index2)
            throw new ArgumentException("index1 must differ from index2");

        Index++;

            /* Generate the golden file names */
        string? name1 = FindGolden(index1);
        string? name2 = FindGolden(index2);
        if (name1 == null || name2 == null) {
            Fail($"index {Index}: golden file for index {(name1 == null ? index1 : index2)} not found");
            return;
        }

            /* Test and record on failure */
        if (!File.ReadAllBytes(name1).AsSpan().SequenceEqual(File.ReadAllBytes(name2)))
            Fail($"index {Index}: comparing {name1} with {name2}");
    }

    // leptonica: regTestWritePixAndCheck (regutils.c)
    /// <summary>Writes the pix and checks it against the golden file with the next index.</summary>
    /// <param name="format">image format, IFF_*</param>
    /// <remarks>
    /// (1) The local file is /tmp/lept/regout/[testname].[NN].[ext].
    /// (2) For png, the local png file is compared with the golden png file by pixels.
    ///     For other formats, the pix is written as png
    ///     (/tmp/lept/regout/[testname].[NN].raw.png) and compared with the
    ///     golden raw png.
    /// </remarks>
    public void WritePixAndCheck(Pix pix, int format)
    {
        if (format < 0 || format >= L.ImageFileFormatExtensions.Length)
            throw new ArgumentException("invalid format");

            /* Write the local file */
        if (pix.Depth < 8)
            pix.SetPadBits(0);

        if (format == L.IFF_PNG) {
            string namebuf = $"/tmp/lept/regout/{TestName}.{Index + 1:D2}.png";
            Pix.WritePng(namebuf, pix, 0.0f);
            CheckFile(namebuf);
            return;
        }

        Index++;
        Pix.Write(GenLocalFilename(Index, format), pix, format);
        string rawlocal = $"/tmp/lept/regout/{TestName}.{Index:D2}.raw.png";
        Pix.WritePng(rawlocal, pix, 0.0f);
        string rawgolden = GoldenName(Index, ".raw.png");
        if (!File.Exists(rawgolden)) {
            Fail($"index {Index}: golden file {rawgolden} not found", "missing", rawlocal, null, null);
            return;
        }
        /* JPEG is bit-exact with libjpeg-turbo; WebP and JPEG 2000 are not yet verified */
        bool allowLossyTolerance = format == L.IFF_WEBP || format == L.IFF_JP2;
        if (!PixFilesEqual(Utils.GenPathname(rawlocal, null), rawgolden, out string detail, allowLossyTolerance))
            Fail($"index {Index}: comparing {rawlocal} with {rawgolden}" +
                 $" ({L.ImageFileFormatExtensions[format]} via raw png){detail}",
                 "file", rawlocal, rawgolden, detail);
    }

    // leptonica: regTestWriteDataAndCheck (regutils.c)
    /// <param name="ext">filename extension (e.g.: "ba", "pta")</param>
    public void WriteDataAndCheck(ReadOnlySpan<byte> data, string ext)
    {
        if (data.Length == 0)
            throw new ArgumentException("data not defined or size == 0");

            /* Generate the local file name */
        string namebuf = $"/tmp/lept/regout/{TestName}.{Index + 1:D2}.{ext}";

            /* Write the local file */
        Utils.BinaryWrite(namebuf, "w", data);

            /* Check the local file against the golden file */
        CheckFile(namebuf);
    }

    // leptonica: regTestGenLocalFilename (regutils.c)
    /// <param name="index">use -1 for current index</param>
    /// <param name="format">image format, IFF_*</param>
    public string GenLocalFilename(int index, int format)
    {
        int ind = (index >= 0) ? index : Index;
        return $"/tmp/lept/regout/{TestName}.{ind:D2}.{L.ImageFileFormatExtensions[format]}";
    }

    /*----------------------------------------------------------------*
     *                             Helpers                            *
     *----------------------------------------------------------------*/
    private void Fail(string what)
    {
        failures.Add($"Failure in {TestName}_reg: {what}");
    }

    /* Fail and, in triage mode, record the check in the LEPT_REGTRIAGE file.
     * local/golden: the files to show side by side (logical /tmp paths are mapped). */
    private void Fail(string what, string kind, string? local, string? golden, string? detail)
    {
        Fail(what);
        if (TriageFile == null)
            return;
        var rec = new Dictionary<string, object?> {
            ["test"] = TestName,
            ["index"] = Index,
            ["kind"] = kind,
            ["local"] = local == null ? null : Utils.GenPathname(local, null),
            ["golden"] = golden == null ? null : Utils.GenPathname(golden, null),
            ["message"] = what,
            ["detail"] = detail,
        };
        string line = JsonSerializer.Serialize(rec) + "\n";
        lock (TriageLock)
            File.AppendAllText(TriageFile, line);
    }

    private string GoldenName(int index, string ext)
    {
        return Path.Combine(TestPaths.GoldenDir!, $"{TestName}_golden.{index:D2}{ext}");
    }

    private string? FindGolden(int index)
    {
        string prefix = $"{TestName}_golden.{index:D2}";
        string[] names = Directory.GetFiles(TestPaths.GoldenDir!, prefix + "*")
                                  .Where(f => !f.EndsWith(".raw.png", StringComparison.Ordinal))
                                  .ToArray();
        return names.Length == 1 ? names[0] : null;
    }

    /* Extension including the dot, as splitPathAtExtension() returns it; "" if none */
    private static string SplitPathAtExtension(string pathname)
    {
        string tail = pathname.Substring(pathname.LastIndexOf('/') + 1);
        int dot = tail.LastIndexOf('.');
        return dot >= 0 ? tail.Substring(dot) : "";
    }

    /* Image files: equal decoded pixels.  Everything else: equal bytes, except that
     * CRLF counts as LF: the goldens come from the Windows build of the C library, which
     * writes some data files (.ba, .na, .pa, ...) in text mode, so they have CRLF line
     * ends where the same C code on unix (and the port) writes LF. */
    private static bool FilesHaveSameContent(string local, string golden, out string detail)
    {
        detail = "";
        bool isImage = Pix.FindFileFormat(golden, out int format) &&
                       format != L.IFF_PS && format != L.IFF_LPDF && format != L.IFF_SPIX;
        if (isImage) {
            bool isTiff = format == L.IFF_TIFF || format == L.IFF_TIFF_PACKBITS ||
                          format == L.IFF_TIFF_RLE || format == L.IFF_TIFF_G3 ||
                          format == L.IFF_TIFF_G4 || format == L.IFF_TIFF_LZW ||
                          format == L.IFF_TIFF_ZIP || format == L.IFF_TIFF_JPEG;
            if (isTiff) {
                using var fs1 = File.OpenRead(local);
                using var fs2 = File.OpenRead(golden);
                Pix.TiffGetCount(fs1, out int count1);
                Pix.TiffGetCount(fs2, out int count2);
                if (count1 > 1 || count2 > 1) {
                    if (count1 != count2) {
                        detail = $" (multipage tiff page count {count1} vs {count2})";
                        return false;
                    }
                    Pixa pa1 = Pixa.ReadMultipageTiff(local);
                    Pixa pa2 = Pixa.ReadMultipageTiff(golden);
                    bool mpSame = pa1.Equal(pa2, 0, out _);
                    if (!mpSame)
                        detail = " (multipage tiff pages differ)";
                    return mpSame;
                }
            }
            /* JPEG is bit-exact with libjpeg-turbo; WebP and JPEG 2000 are not yet verified */
            bool allowLossyTolerance = format == L.IFF_WEBP || format == L.IFF_JP2;
            return PixFilesEqual(local, golden, out detail, allowLossyTolerance);
        }
            /* Serialized pixa embed png data: compare the decoded pixa */
        if (golden.EndsWith(".pa", StringComparison.Ordinal)) {
            bool same = Pixa.Read(local).Equal(Pixa.Read(golden), 0, out _);
            if (!same)
                detail = " (pixa differ)";
            return same;
        }
            /* Serialized pixacomp embed compressed png/jpeg/tiff data: compare decoded pix */
        if (golden.EndsWith(".pac", StringComparison.Ordinal)) {
            Pixacomp pac1 = Pixacomp.Read(local);
            Pixacomp pac2 = Pixacomp.Read(golden);
            if (pac1.Count != pac2.Count) {
                detail = $" (pixacomp count {pac1.Count} vs {pac2.Count})";
                return false;
            }
            for (int i = 0; i < pac1.Count; i++) {
                Pix p1 = pac1.GetPix(i);
                Pix p2 = pac2.GetPix(i);
                if (!Pix.Equal(p1, p2) &&
                    !(p1.Width == p2.Width && p1.Height == p2.Height && p1.Depth == p2.Depth &&
                      p1.TestForSimilarity(p2, 1, 25, 0.05f, 0.0f, 0))) {
                    detail = $" (pixacomp item {i} differs)";
                    return false;
                }
            }
            return true;
        }
        byte[] bytes1 = File.ReadAllBytes(local), bytes2 = File.ReadAllBytes(golden);
        if (bytes1.AsSpan().SequenceEqual(bytes2))
            return true;
        if (StripCR(bytes1).AsSpan().SequenceEqual(StripCR(bytes2)))
            return true;
        if (format == L.IFF_LPDF || golden.EndsWith(".pdf", StringComparison.OrdinalIgnoreCase)) {
            if (PdfStructureEquals(local, golden, out detail))
                return true;
            return false;
        }
        if (format == L.IFF_PS || golden.EndsWith(".ps", StringComparison.OrdinalIgnoreCase)) {
            if (PsStructureEquals(bytes1, bytes2, out detail))
                return true;
            return false;
        }
        detail = " (data files differ)";
        return false;
    }

    private static bool PdfStructureEquals(string local, string golden, out string detail)
    {
        detail = "";
        try {
            int p1 = PdfIo.GetPageCount(local);
            int p2 = PdfIo.GetPageCount(golden);
            if (p1 <= 0 || p1 != p2) {
                detail = $" (pdf page count {p1} vs {p2})";
                return false;
            }
            PdfIo.GetPageSizes(local, out Numa aw, out Numa ah, out _, out _);
            PdfIo.GetPageSizes(golden, out Numa gw, out Numa gh, out _, out _);
            if (!aw.GetIArray().AsSpan().SequenceEqual(gw.GetIArray()) ||
                !ah.GetIArray().AsSpan().SequenceEqual(gh.GetIArray())) {
                detail = " (pdf page sizes differ)";
                return false;
            }
            PdfIo.GetMediaBoxSizes(local, out Numa amw, out Numa amh, out _, out _);
            PdfIo.GetMediaBoxSizes(golden, out Numa gmw, out Numa gmh, out _, out _);
            if (!amw.GetIArray().AsSpan().SequenceEqual(gmw.GetIArray()) ||
                !amh.GetIArray().AsSpan().SequenceEqual(gmh.GetIArray())) {
                detail = " (pdf media boxes differ)";
                return false;
            }
            return true;
        } catch (Exception ex) {
            detail = $" (pdf parse failed: {ex.Message})";
            return false;
        }
    }

    private static bool PsStructureEquals(byte[] local, byte[] golden, out string detail)
    {
        detail = "";
        string s1 = System.Text.Encoding.Latin1.GetString(StripCR(local));
        string s2 = System.Text.Encoding.Latin1.GetString(StripCR(golden));
        if (!s1.StartsWith("%!PS-Adobe", StringComparison.Ordinal) ||
            !s2.StartsWith("%!PS-Adobe", StringComparison.Ordinal)) {
            detail = " (missing PS header)";
            return false;
        }
        static string[] ExtractMeta(string s) =>
            s.Split('\n')
             .Where(l => l.StartsWith("%%Page:", StringComparison.Ordinal) ||
                         l.StartsWith("%%Pages:", StringComparison.Ordinal) ||
                         l.StartsWith("%%BoundingBox:", StringComparison.Ordinal))
             .ToArray();
        if (!ExtractMeta(s1).AsSpan().SequenceEqual(ExtractMeta(s2))) {
            detail = " (PS page/boundingbox metadata differ)";
            return false;
        }
        return true;
    }

    /* CRLF -> LF */
    private static byte[] StripCR(byte[] data)
    {
        var list = new List<byte>(data.Length);
        for (int i = 0; i < data.Length; i++) {
            if (data[i] == '\r' && i + 1 < data.Length && data[i + 1] == '\n')
                continue;
            list.Add(data[i]);
        }
        return list.ToArray();
    }

    private static bool PixFilesEqual(string local, string golden, out string detail, bool allowLossyTolerance = false)
    {
        detail = "";
        Pix pix1, pix2;
        try {
            lock (TestPaths.PngReadLock) {
                pix1 = Pix.Read(local);
                pix2 = Pix.Read(golden);
            }
        } catch (NotImplementedException e) {
            detail = $" (cannot decode: {e.Message})";
            return false;
        }
        bool same = Pix.Equal(pix1, pix2);
        if (!same && allowLossyTolerance &&
            pix1.Width == pix2.Width && pix1.Height == pix2.Height && pix1.Depth == pix2.Depth) {
            same = pix1.TestForSimilarity(pix2, 1, 25, 0.05f, 0.0f, 0);
        }
        if (!same)
            detail = $" (pixels differ: {pix1.Width}x{pix1.Height}x{pix1.Depth} " +
                     $"vs {pix2.Width}x{pix2.Height}x{pix2.Depth})";
        return same;
    }
}
